// Generated from the preset spec. Every preset has been rendered offline,
// level-matched (master) and checked for tonal balance and similarity.

struct MacroTarget { const char* id; float amount; };
struct MacroDef    { const char* name; MacroTarget targets[3]; };
struct MacroTemplate { MacroDef macros[8]; };

enum MacroTemplateId { TPad = 0, TLead, TKeys, TBass, TArp, TFx, TCine, numMacroTemplates };

